from __future__ import annotations

from typing import Any

from limiter_store import LimiterStore
from rate_limiter import SlidingWindowLimiter


class ApiGateway:
    def __init__(self, max_requests: int = 5, window_ms: int = 1000) -> None:
        self.store = LimiterStore()
        self.limiter = SlidingWindowLimiter(
            store=self.store,
            max_requests=max_requests,
            window_ms=window_ms,
        )

    def handle_request(self, payload: dict[str, Any]) -> dict[str, Any]:
        client_id = str(payload.get("client_id", "")).strip()
        now_ms = int(payload.get("now_ms", 0))
        path = str(payload.get("path", "/v1/default")).strip() or "/v1/default"

        check = self.limiter.check(client_id, now_ms)
        if not check.get("allowed"):
            return {
                "ok": False,
                "reason": check.get("reason", "rate_limited"),
                "status": 429,
                "remaining": check.get("remaining", 0),
                "path": path,
            }

        return {
            "ok": True,
            "reason": "handled",
            "status": 200,
            "remaining": check.get("remaining", 0),
            "path": path,
        }

    def handle_batch(self, payloads: list[dict[str, Any]]) -> dict[str, Any]:
        outputs: list[dict[str, Any]] = []
        allowed = 0
        blocked = 0
        for payload in payloads:
            output = self.handle_request(payload)
            outputs.append(output)
            if output.get("ok"):
                allowed += 1
            else:
                blocked += 1
        return {"allowed": allowed, "blocked": blocked, "outputs": outputs}

    def diagnostics(self, client_id: str, now_ms: int) -> dict[str, Any]:
        return {
            "window": self.limiter.inspect(client_id, now_ms),
            "client_count": self.store.client_count(),
            "snapshot": self.store.snapshot(),
        }

    def reset(self) -> None:
        self.limiter.reset_all()

    def handle_with_headers(self, payload: dict[str, Any]) -> dict[str, Any]:
        result = self.handle_request(payload)
        now_ms = int(payload.get("now_ms", 0))
        client_id = str(payload.get("client_id", "")).strip()
        explain = self.limiter.explain(client_id, now_ms)
        result["headers"] = {
            "x-rate-limit-limit": explain["max_requests"],
            "x-rate-limit-remaining": explain["remaining"],
            "x-rate-limit-retry-after-ms": explain["retry_after_ms"],
        }
        return result

    def inspect_client(self, client_id: str, now_ms: int) -> dict[str, Any]:
        return self.limiter.explain(client_id, now_ms)

    def summary(self) -> dict[str, int]:
        return {"clients": self.store.client_count(), "cache_entries": len(self.store.snapshot())}

    def has_client(self, client_id: str) -> bool:
        return self.store.has_client(client_id)

