from __future__ import annotations

from collections import deque
from threading import Lock
from typing import Any


class LimiterStore:
    def __init__(self) -> None:
        self._lock = Lock()
        self._hits: dict[str, deque[int]] = {}

    def _queue_for(self, client_id: str) -> deque[int]:
        key = client_id.strip()
        if not key:
            raise ValueError("client_id required")
        queue = self._hits.get(key)
        if queue is None:
            queue = deque()
            self._hits[key] = queue
        return queue

    def add_hit(self, client_id: str, ts_ms: int) -> None:
        if ts_ms < 0:
            raise ValueError("ts_ms must be >= 0")
        with self._lock:
            queue = self._queue_for(client_id)
            queue.append(int(ts_ms))

    def trim_before(self, client_id: str, min_ts_ms: int) -> int:
        removed = 0
        with self._lock:
            queue = self._queue_for(client_id)
            while queue and queue[0] < min_ts_ms:
                queue.popleft()
                removed += 1
        return removed

    def count(self, client_id: str) -> int:
        with self._lock:
            queue = self._queue_for(client_id)
            return len(queue)

    def list_hits(self, client_id: str) -> list[int]:
        with self._lock:
            queue = self._queue_for(client_id)
            return list(queue)

    def clear_client(self, client_id: str) -> None:
        key = client_id.strip()
        if not key:
            return
        with self._lock:
            self._hits.pop(key, None)

    def clear_all(self) -> None:
        with self._lock:
            self._hits.clear()

    def snapshot(self) -> dict[str, Any]:
        with self._lock:
            return {key: list(queue) for key, queue in self._hits.items()}

    def client_count(self) -> int:
        with self._lock:
            return len(self._hits)

    def has_client(self, client_id: str) -> bool:
        key = client_id.strip()
        if not key:
            return False
        with self._lock:
            return key in self._hits

    def first_hit(self, client_id: str) -> int | None:
        with self._lock:
            queue = self._queue_for(client_id)
            if not queue:
                return None
            return int(queue[0])

    def last_hit(self, client_id: str) -> int | None:
        with self._lock:
            queue = self._queue_for(client_id)
            if not queue:
                return None
            return int(queue[-1])

    def trim_all_before(self, min_ts_ms: int) -> int:
        removed = 0
        with self._lock:
            for queue in self._hits.values():
                while queue and queue[0] < min_ts_ms:
                    queue.popleft()
                    removed += 1
        return removed

