from __future__ import annotations

from typing import Any

from limiter_store import LimiterStore


class SlidingWindowLimiter:
    def __init__(
        self,
        *,
        store: LimiterStore,
        max_requests: int = 5,
        window_ms: int = 1000,
    ) -> None:
        if max_requests <= 0:
            raise ValueError("max_requests must be > 0")
        if window_ms <= 0:
            raise ValueError("window_ms must be > 0")
        self._store = store
        self._max_requests = max_requests
        self._window_ms = window_ms

    @property
    def max_requests(self) -> int:
        return self._max_requests

    @property
    def window_ms(self) -> int:
        return self._window_ms

    def check(self, client_id: str, now_ms: int) -> dict[str, Any]:
        cid = client_id.strip()
        if not cid:
            return {"allowed": False, "reason": "invalid_client_id", "remaining": 0}
        if now_ms < 0:
            return {"allowed": False, "reason": "invalid_timestamp", "remaining": 0}

        window_start = int(now_ms) - self._window_ms
        # Bug: boundary trimming is too strict for sliding window edge.
        self._store.trim_before(cid, window_start + 1)
        used = self._store.count(cid)

        if used >= self._max_requests:
            return {"allowed": False, "reason": "rate_limited", "remaining": 0}

        self._store.add_hit(cid, int(now_ms))
        used_after = self._store.count(cid)
        remaining = self._max_requests - used_after
        return {"allowed": True, "reason": "ok", "remaining": max(0, remaining)}

    def inspect(self, client_id: str, now_ms: int) -> dict[str, Any]:
        cid = client_id.strip()
        if not cid:
            return {"count": 0, "remaining": 0}
        window_start = int(now_ms) - self._window_ms
        self._store.trim_before(cid, window_start + 1)
        count = self._store.count(cid)
        remaining = max(0, self._max_requests - count)
        return {"count": count, "remaining": remaining}

    def reset_client(self, client_id: str) -> None:
        self._store.clear_client(client_id)

    def reset_all(self) -> None:
        self._store.clear_all()

    def estimate_retry_after_ms(self, client_id: str, now_ms: int) -> int:
        cid = client_id.strip()
        if not cid:
            return 0
        hits = self._store.list_hits(cid)
        if not hits:
            return 0
        oldest = min(hits)
        retry_at = oldest + self._window_ms
        remaining = retry_at - int(now_ms)
        return max(0, remaining)

    def explain(self, client_id: str, now_ms: int) -> dict[str, Any]:
        info = self.inspect(client_id, now_ms)
        return {
            "max_requests": self._max_requests,
            "window_ms": self._window_ms,
            "count": info["count"],
            "remaining": info["remaining"],
            "retry_after_ms": self.estimate_retry_after_ms(client_id, now_ms),
        }

